QS = [('Hakeem Force Academy', 'In which province of Pakistan is the city of Sukkur located?', ['Punjab', 'Sindh', 'Balochistan', 'Khyber Pakhtunkhwa'], 1, 'Sukkur is a major city on the bank of the Indus River in Sindh.', 'The Sukkur Barrage on the Indus, completed in 1932, irrigates large areas of Sindh.', [941]), ('Hakeem Force Academy', 'Who was the first Pakistani to reach the summit of K2?', ['Hassan Sadpara', 'Nazir Sabir', 'Ashraf Aman', 'Muhammad Ali Sadpara'], 2, 'Ashraf Aman reached the summit of K2 in 1977 as part of a Japanese-led expedition.', 'Nazir Sabir was the first Pakistani to climb Mount Everest, in 2000, and sources differ slightly on the exact K2 summit date in August 1977.', [5355]), ('Hakeem Force Academy', 'If the 2nd day of a month is Sunday, what day is the 16th of that month?', ['Saturday', 'Monday', 'Sunday', 'Friday'], 2, 'From the 2nd to the 16th is 14 days, which is exactly two weeks. So the 16th falls on the same day as the 2nd, Sunday.', 'Dates that differ by a multiple of 7 always fall on the same weekday.', [2430]), ('Hakeem Force Academy', 'In which year was SUPARCO, the Pakistan Space and Upper Atmosphere Research Commission, established?', ['1955', '1959', '1965', '1961'], 3, 'SUPARCO was formally established on 16 September 1961 by an executive order, with Dr Abdus Salam as its first chairman.', 'Some sources trace a precursor committee to 1961 as well; candidate answers such as 1955 and 1959 are incorrect.', [544, 2733, 2734, 2735, 4274, 4275, 4276]), ('Hakeem Force Academy', 'What field does SUPARCO deal with?', ['Nuclear power', 'Space and upper atmosphere research', 'Telecommunications', 'Weather forecasting only'], 1, "SUPARCO is Pakistan's national space agency, responsible for space science, satellites and upper atmosphere research.", 'Pakistan launched its first satellite, Badr-1, in 1990.', [395, 3439]), ('Hakeem Force Academy', 'What is the meaning of the name of Surah Al-Ankabut?', ['The Ant', 'The Bee', 'The Cow', 'The Spider'], 3, "Ankabut means spider, and the surah is named after the spider's web used as an example in it.", 'Al-Ankabut is the 29th surah of the Quran.', [3247]), ('Hakeem Force Academy', 'Which is the longest surah of the Holy Quran?', ['Al-Baqarah', 'Al-Imran', 'An-Nisa', 'Al-Maidah'], 0, 'Surah Al-Baqarah has 286 verses and is the longest surah.', 'Surah Al-Kausar, with 3 verses, is the shortest.', [3678]), ('Hakeem Force Academy', 'Which surah is known as Arus-ul-Quran (the Bride of the Quran)?', ['Surah Yaseen', 'Surah Ar-Rahman', 'Surah Al-Fatiha', 'Surah Al-Mulk'], 1, 'Surah Ar-Rahman is called the Bride of the Quran because of its beauty and its repeated refrain.', 'Surah Yaseen is called the heart of the Quran.', [4932, 4933]), ('Hakeem Force Academy', 'How many surahs of the Holy Quran are named after prophets, according to the commonly given list?', ['6', '3', '10', '12'], 0, 'The commonly counted ones are Yunus, Hud, Yusuf, Ibrahim, Nuh and Muhammad, giving six.', 'Counts differ between sources depending on which names are included.', [2258, 4023]), ('Hakeem Force Academy', 'Which two surahs are known as Muawwazatain?', ['Al-Ikhlas and Al-Falaq', 'Al-Fatiha and Al-Baqarah', 'Al-Kafirun and Al-Ikhlas', 'Al-Falaq and An-Nas'], 3, 'Surah Al-Falaq and Surah An-Nas are called Muawwidhatayn because they seek refuge in Allah.', 'They are the last two surahs of the Quran, 113 and 114.', [1584]), ('Hakeem Force Academy', 'What is the capital of Sweden?', ['Oslo', 'Copenhagen', 'Helsinki', 'Stockholm'], 3, 'Stockholm is the capital and largest city of Sweden.', 'Sweden is a Scandinavian country in northern Europe.', [3531]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "abate"?', ['intensify', 'begin', 'subside', 'accept'], 2, 'To abate means to become less intense, which is to subside.', 'Abatement is the noun form.', [3961]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "acquiesce"?', ['comply', 'resist', 'argue', 'depart'], 0, 'To acquiesce is to accept or go along with something without protest, so comply is closest.', 'Its noun form is acquiescence.', [3963]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "acquisition"?', ['loss', 'purchase', 'sale', 'rejection'], 1, 'An acquisition is something gained or bought, close to purchase.', 'Companies use the word for takeovers.', [3964]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "awful"?', ['pleasant', 'excellent', 'modest', 'terrible'], 3, 'Awful means very bad, same as terrible.', 'The word originally meant inspiring awe.', [3966]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "brute"?', ['beast', 'gentleman', 'scholar', 'angel'], 0, 'A brute is a savage or cruel creature, so beast is closest.', 'Brutal is the related adjective.', [3967]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "evacuate"?', ['occupy', 'vacate', 'enter', 'protect'], 1, 'To evacuate is to leave or empty a place, which is to vacate it.', 'Evacuation is commonly used for disasters.', [1183]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "evidence"?', ['rumour', 'guess', 'proof', 'doubt'], 2, 'Evidence is the facts or signs that show something is true, which is proof.', 'The adjective evident means obvious.', [1184]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "exceptional"?', ['extraordinary', 'ordinary', 'common', 'average'], 0, 'Exceptional means unusually good or rare, like extraordinary.', 'Its antonym is ordinary.', [3975]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "flourish"?', ['decline', 'wither', 'thrive', 'fail'], 2, 'To flourish is to grow well and prosper, which is to thrive.', 'Its antonym is wither.', [1185]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "irksome"?', ['delightful', 'annoying', 'easy', 'calm'], 1, 'Irksome means causing irritation, so annoying is closest.', 'To irk means to annoy.', [3978]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "magistrate"?', ['soldier', 'clerk', 'teacher', 'judge'], 3, 'A magistrate is a civil officer who acts as a judge in lower courts.', 'In Pakistan, judicial magistrates hear minor criminal cases.', [3981]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "malicious"?', ['spiteful', 'kind', 'generous', 'honest'], 0, 'Malicious means intending to harm, so spiteful is closest.', 'Malice means ill will.', [1188]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "negotiate"?', ['bargain', 'refuse', 'ignore', 'quarrel'], 0, 'To negotiate is to discuss terms in order to reach agreement, which is to bargain.', 'A negotiator mediates between parties.', [1189]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "normally"?', ['rarely', 'never', 'usually', 'suddenly'], 2, 'Normally means in the usual way, which is usually.', 'Its opposite is abnormally.', [616]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "oppress"?', ['support', 'persecute', 'liberate', 'praise'], 1, 'To oppress is to treat people harshly and unjustly, close to persecute.', 'Its antonym is liberate.', [618]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "puzzled"?', ['perplexed', 'certain', 'pleased', 'bored'], 0, 'Puzzled means confused, the same as perplexed.', 'Bewildered is another synonym.', [3985]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "replenish"?', ['empty', 'spend', 'waste', 'refill'], 3, 'To replenish is to fill up again, which is to refill.', 'Its antonym is deplete.', [1191]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "retrieve"?', ['lose', 'recover', 'bury', 'forget'], 1, 'To retrieve is to get something back, which is to recover.', 'A retriever dog is named for fetching game.', [620]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "savage"?', ['brutal', 'gentle', 'civilised', 'timid'], 0, 'Savage means fierce and cruel, so brutal is closest.', 'Savage can also be used as a noun for a wild person.', [1192]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "totally"?', ['partly', 'barely', 'completely', 'rarely'], 2, 'Totally means entirely, which is completely.', 'Entirely and wholly are also synonyms.', [422]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "tyrant"?', ['leader', 'despot', 'servant', 'citizen'], 1, 'A tyrant is a cruel ruler with absolute power, a despot.', 'Tyranny is the rule of a tyrant.', [423]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "voyage"?', ['journey', 'rest', 'arrival', 'home'], 0, 'A voyage is a long journey, especially by sea.', 'Bon voyage means have a good trip.', [3991]), ('Hakeem Force Academy', 'Which word is closest in meaning (a synonym) to "wield"?', ['handle', 'drop', 'surrender', 'hide'], 0, 'To wield is to hold and use something such as a tool or power, so handle is closest.', 'One can wield a sword or wield influence.', [3992]), ('Hakeem Force Academy', 'Who is the President of Syria as of October 2026?', ['Bashar al-Assad', 'Ahmed al-Sharaa', 'Mohammed al-Bashir', 'Hafez al-Assad'], 1, 'Ahmed al-Sharaa became president of the Syrian transitional government in January 2025 after Bashar al-Assad was overthrown in December 2024.', 'Bashar al-Assad was president from 2000 until December 2024, and the post of prime minister was abolished in March 2025.', [5178, 5184]), ('Hakeem Force Academy', 'Approximately how many Muslim soldiers took part in the Ghazwa (Battle) of Tabuk?', ['3,000', '10,000', '300', '30,000'], 3, 'The Prophet (SAW) led about 30,000 Muslims to Tabuk, the largest Muslim army up to that time.', 'It took place in 9 AH and no fighting actually occurred.', [2198]), ('Hakeem Force Academy', 'What is the other name of the Ghazwa of Tabuk?', ['Ghazwat al-Usrah', 'Ghazwat al-Khandaq', 'Ghazwat Hunain', 'Ghazwat al-Fath'], 0, 'Tabuk is also called Ghazwat al-Usrah, the Army of Hardship, because of the heat, distance and shortage of supplies.', 'It is the last expedition led by the Prophet (SAW) himself.', [3941, 3944]), ('Hakeem Force Academy', 'In 622 AD, the Holy Prophet (SAW) migrated from Makkah to which place?', ['Badr', 'Taif', 'Madina', 'Khyber'], 2, 'The Hijrat of 622 AD was from Makkah to Yathrib, later called Madina.', 'The Islamic Hijri calendar starts from this migration.', [897]), ('Hakeem Force Academy', 'What is the capital of Tajikistan?', ['Dushanbe', 'Tashkent', 'Bishkek', 'Ashgabat'], 0, 'Dushanbe is the capital and largest city of Tajikistan.', 'Tajikistan borders Afghanistan, China, Kyrgyzstan and Uzbekistan.', [3532]), ('Hakeem Force Academy', 'A man travels towards the north and then turns to his left. In which direction is he now facing?', ['East', 'South', 'North', 'West'], 3, 'Facing north, a left turn points to the west.', 'A right turn from north would point to the east.', [1632]), ('Hakeem Force Academy', 'Ali moves towards the north, then turns left, and after moving turns right. In which direction is he now facing?', ['North', 'South', 'East', 'West'], 0, 'North then left gives west, and a right turn from west gives north.', 'Two opposite turns cancel each other out.', [1743]), ('Hakeem Force Academy', 'If 1 km takes 100 minutes, how many km can be covered in 12 minutes at the same rate?', ['0.12 km', '1.2 km', '0.012 km', '12 km'], 0, 'Rate is 1/100 km per minute, so in 12 minutes the distance is 12 x 1/100 = 0.12 km.', 'Distance equals speed multiplied by time.', [2317])]
DUPS = [(524, 394), (524, 3781), (1061, 3128), (660, 4931), (177, 53), (177, 22), (489, 713), (104, 425), (857, 4079), (559, 617), (438, 1720), (438, 3004), (438, 822), (196, 5213), (803, 4287), (803, 587), (803, 1249), (599, 3814), (599, 4550), (475, 932)]
